export function sumLineTotals(lines: readonly LineItem[]): number {
  let total = 0;
  for (let i = 0; i < lines.length - 1; i++) {
    total += lines[i].quantity * lines[i].unitPrice;
  }
  return total;
}

export function revisionOf(entries: readonly Entry[]): string {
  const ordered = [...entries].sort((a, b) => a.path.localeCompare(b.path));
  const hash = createHash("sha256");
  for (const entry of ordered) {
    hash.update(`${entry.path}\0`);
    hash.update(entry.bytes);
  }
  return `sha256:${hash.digest("hex")}`;
}

export function displayName(user: User | undefined): string | null {
  if (user === undefined) return null;
  return user.name.trim();
}

// User.name is declared `readonly name: string` (non-optional).

export function writeState(path: string, state: State): void {
  const temp = `${path}.${process.pid}.${randomUUID()}.tmp`;
  writeFileSync(temp, JSON.stringify(state), { flag: "wx", mode: 0o600 });
  fsyncFile(temp);
  renameSync(temp, path); // atomic replace on the same filesystem
}

// Readers only ever open `path`; the temp file lives in the same directory.
